function packetProfiles(activeOnly=false){const profiles=config.packet_profiles||[];for(const key of Object.keys(decoderProfiles))delete decoderProfiles[key];for(const p of profiles)if(p.active)decoderProfiles[p.id]={label:`${p.name} (${p.layout} bytes)`,layout:p.layout};return activeOnly?profiles.filter(p=>p.active):profiles;}
