    const remove=$('#remove-dongle');if(remove)remove.onclick=async()=>{try{if(!confirm(`Remove ${m.name}?`))return;maps[slot]={ip:'',name:`INVERTER${slot+1}`,profile:defaultProfile(),cloud_forward:true};await saveDongles(maps,'Dongle removed.');close();await refresh();}catch(error){notice(error.message,true);}};
    const reboot=$('#dongle-reboot');if(reboot)reboot.onclick=async()=>{try{if(!confirm(`Reboot ${m.name}?`))return;await api('dongle-reboot',{ip:m.ip});notice('Reboot requested.');}catch(error){notice(error.message,true);}};
